cpp.code:
#include <iostream>
#include <vector>
#include <string>

std::vector<std::string> namen = {"Anna", "Ben", "Clara"};
for (const auto& name : namen) {
    std::cout << name << std::endl;
}

for (char buchstabe : std::string("Hallo")) {
    std::cout << buchstabe << std::endl;
}

