cpp.code:
int versuche = 0;
int eingabe;
while (true) {
    std::cin >> eingabe;
    versuche++;
    if (eingabe == 42) {
        std::cout << "Richtig!";
        break;
    }
    if (versuche >= 3) break;
}

for (int i = 0; i < 10; i++) {
    if (i % 2 == 0) continue;   // nächste Runde
    std::cout << i;             // ungerade Zahlen
}
